{"path": "src/db.js", "content": "require('dotenv').config();
const mongoose = require('mongoose');

// Singleton mongoose connection per documentdb-driver & documentdb-connection guidance
let isConnected = false;

async function connect() {
  if (isConnected) return mongoose;
  const uri = process.env.DOCUMENTDB_URI;
  if (!uri) throw new Error('DOCUMENTDB_URI environment variable is required');

  // Use safe defaults for an OLTP long-running server; guidance suggests tune per workload
  const opts = {
    // Mongoose will pass these to the underlying MongoClient
    maxPoolSize: 50,
    minPoolSize: 10,
    connectTimeoutMS: 10000,
    serverSelectionTimeoutMS: 5000,
    tls: true,
  };

  await mongoose.connect(uri, opts);
  isConnected = true;
  return mongoose;
}

module.exports = { connect };
"}

{"path": "src/models/interaction.js", "content": "const mongoose = require('mongoose');

const InteractionSchema = new mongoose.Schema({
  drugA: { type: String, required: true, index: true },
  drugB: { type: String, required: true, index: true },
  normalizedPair: { type: String, required: true, unique: true, index: true },
  severityScore: { type: Number, default: null },
  clinicalRecommendation: { type: String, default: '' },
  evidence: { type: [String], default: [] },
  updatedAt: { type: Date, default: Date.now }
}, { collection: 'interactions' });

InteractionSchema.pre('save', function(next) {
  this.updatedAt = new Date();
  next();
});

module.exports = mongoose.models.Interaction || mongoose.model('Interaction', InteractionSchema);
"}

